UPDATE POST
SET IS_BLIND = #{isBlind}
WHERE POST_ID = #{postId}
  AND IS_DELETED = 0

mapper.sql:
WHERE M.ROLE IN ('STU', 'PROF', 'ALU')

    AND (
        LOWER(M.MEMBER_NAME) LIKE '%' || LOWER(#{keyword}) || '%'
        OR LOWER(M.LOGIN_ID) LIKE '%' || LOWER(#{keyword}) || '%'
    )


    AND M.STATUS = #{status}


    AND M.UNIV_ID = #{univId}

mapper.update:
UPDATE MEMBER
SET STATUS = #{status}
WHERE MEMBER_ID = #{memberId}
  AND ROLE IN ('STU', 'PROF', 'ALU')
